CREATE TABLE public.cleaning_teams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN ('owner_helper','paired_pros')),lead_pro_id uuid NOT NULL,partner_pro_id uuid,helper_name text,helper_background_checked_at timestamptz,helper_insurance_verified_at timestamptz,active boolean NOT NULL DEFAULT true,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),CHECK((kind='paired_pros' AND partner_pro_id IS NOT NULL AND partner_pro_id<>lead_pro_id) OR (kind='owner_helper' AND partner_pro_id IS NULL AND length(trim(helper_name))>=2)));
GRANT SELECT ON public.cleaning_teams TO authenticated; GRANT ALL ON public.cleaning_teams TO service_role;
ALTER TABLE public.cleaning_teams ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_team_read ON public.cleaning_teams FOR SELECT TO authenticated USING(public.current_user_admin() OR lead_pro_id=auth.uid() OR partner_pro_id=auth.uid());
ALTER TABLE public.reservations ADD COLUMN cleaning_team_id uuid REFERENCES public.cleaning_teams(id);
ALTER TABLE public.subscriptions ADD COLUMN cleaning_team_id uuid REFERENCES public.cleaning_teams(id);
ALTER TABLE public.visits ADD COLUMN cleaning_team_id uuid REFERENCES public.cleaning_teams(id),ADD COLUMN cleaning_first_visit boolean NOT NULL DEFAULT false,ADD COLUMN cleaning_final_inspection_at timestamptz,ADD COLUMN cleaning_zones jsonb NOT NULL DEFAULT '[]';
CREATE TABLE public.cleaning_pay_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),visit_id uuid NOT NULL REFERENCES public.visits(id),pro_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('base','first_visit','partial','addon','redo','review')),amount_cents integer NOT NULL,dedupe_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cleaning_pay_lines TO authenticated; GRANT ALL ON public.cleaning_pay_lines TO service_role;
ALTER TABLE public.cleaning_pay_lines ENABLE ROW LEVEL SECURITY;
CREATE POLICY cleaning_pay_private ON public.cleaning_pay_lines FOR SELECT TO authenticated USING(pro_id=auth.uid() OR public.current_user_admin());
CREATE OR REPLACE FUNCTION public.cleaning_team_valid(_team uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT active AND public.sched_pro_active(lead_pro_id) AND 'cleaning'::public.service_type=ANY(public.sched_pro_services(lead_pro_id)) AND CASE WHEN kind='paired_pros' THEN public.sched_pro_active(partner_pro_id) AND 'cleaning'::public.service_type=ANY(public.sched_pro_services(partner_pro_id)) ELSE helper_background_checked_at IS NOT NULL AND helper_insurance_verified_at IS NOT NULL END FROM public.cleaning_teams WHERE id=_team),false) $$;
REVOKE ALL ON FUNCTION public.cleaning_team_valid(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cleaning_team_valid(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.admin_cleaning_team(_kind text,_lead uuid,_partner uuid DEFAULT NULL,_helper text DEFAULT NULL,_background boolean DEFAULT false,_insured boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; BEGIN IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; IF NOT public.sched_pro_active(_lead) OR NOT ('cleaning'::public.service_type=ANY(public.sched_pro_services(_lead))) THEN RAISE EXCEPTION 'lead_not_assignable'; END IF; IF _kind='paired_pros' AND (NOT public.sched_pro_active(_partner) OR NOT ('cleaning'::public.service_type=ANY(public.sched_pro_services(_partner)))) THEN RAISE EXCEPTION 'partner_not_assignable'; END IF; IF _kind='owner_helper' AND (NOT _background OR NOT _insured) THEN RAISE EXCEPTION 'helper_verification_required'; END IF; INSERT INTO public.cleaning_teams(kind,lead_pro_id,partner_pro_id,helper_name,helper_background_checked_at,helper_insurance_verified_at,created_by) VALUES(_kind,_lead,_partner,_helper,CASE WHEN _background THEN now() END,CASE WHEN _insured THEN now() END,auth.uid()) RETURNING id INTO tid; RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.admin_cleaning_team(text,uuid,uuid,text,boolean,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_cleaning_team(text,uuid,uuid,text,boolean,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_cleaning_staff(_reservation uuid,_team uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.current_user_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; IF NOT public.cleaning_team_valid(_team) THEN RAISE EXCEPTION 'team_not_verified'; END IF; UPDATE public.reservations SET cleaning_team_id=_team,cleaning_team_ready=true,updated_at=now() WHERE id=_reservation AND status IN ('reserved','invited') AND cleaning_verified_size='5'; IF NOT FOUND THEN RAISE EXCEPTION 'estate_plus_reservation_required'; END IF; END $$;
REVOKE ALL ON FUNCTION public.admin_cleaning_staff(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_cleaning_staff(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.cleaning_conversion_block(r public.reservations) RETURNS text LANGUAGE sql STABLE SET search_path=public AS $$ SELECT CASE WHEN NOT ('cleaning'=ANY(r.services)) THEN NULL WHEN r.cleaning_verified_at IS NULL THEN 'cleaning_unverified' WHEN r.cleaning_verified_size='custom' THEN 'cleaning_walkthrough_required' WHEN r.cleaning_size_confirmation NOT IN ('confirmed','not_needed') OR r.cleaning_size_confirmation IS NULL THEN 'cleaning_size_unconfirmed' WHEN r.cleaning_verified_size='5' AND (NOT r.cleaning_team_ready OR NOT public.cleaning_team_valid(r.cleaning_team_id)) THEN 'cleaning_needs_team' ELSE NULL END $$;
CREATE OR REPLACE FUNCTION public.contractor_visit_pay_cents(_service text,_size smallint,_cadence text,_tier text DEFAULT NULL,_surcharge boolean DEFAULT false,_visit_kind text DEFAULT NULL) RETURNS integer LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE base integer; BEGIN IF _service='cleaning' THEN base:=CASE _size WHEN 1 THEN 5600 WHEN 2 THEN 7600 WHEN 3 THEN 11200 WHEN 4 THEN 17000 WHEN 5 THEN 23800 END; ELSIF _service='lawn' THEN base:=CASE _size WHEN 1 THEN 1800 WHEN 2 THEN 2600 WHEN 3 THEN 4000 END; ELSIF _service='detailing' THEN base:=CASE _size WHEN 1 THEN CASE WHEN _visit_kind='full_detail' THEN 7800 ELSE 1600 END WHEN 2 THEN CASE WHEN _visit_kind='full_detail' THEN 8800 ELSE 2000 END WHEN 3 THEN CASE WHEN _visit_kind='full_detail' THEN 11500 ELSE 2600 END END; END IF; IF _tier='tier_2_pro_partner' THEN base:=(round(base::numeric/100*1.1)*100)::integer; END IF; RETURN base; END $$;
CREATE OR REPLACE FUNCTION public.cleaning_visit_staff_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE tid uuid; lead uuid; BEGIN IF NEW.service::text<>'cleaning' OR NEW.size_tier NOT IN (4,5) OR NEW.status::text IN ('canceled','skipped','complete','blocked') THEN RETURN NEW; END IF; IF NEW.size_tier=5 THEN SELECT cleaning_team_id INTO tid FROM public.subscriptions WHERE id=NEW.subscription_id; NEW.cleaning_team_id:=coalesce(NEW.cleaning_team_id,tid); IF NEW.assigned_pro_id IS NOT NULL AND NOT public.cleaning_team_valid(NEW.cleaning_team_id) THEN RAISE EXCEPTION 'estate_plus_needs_verified_team'; END IF; SELECT lead_pro_id INTO lead FROM public.cleaning_teams WHERE id=NEW.cleaning_team_id; IF NEW.assigned_pro_id IS NOT NULL AND NEW.assigned_pro_id IS DISTINCT FROM lead THEN RAISE EXCEPTION 'estate_plus_lead_required'; END IF; END IF; NEW.time_window:='8–10 AM + 11 AM–1 PM'; RETURN NEW; END $$;
CREATE TRIGGER cleaning_visit_staff_guard BEFORE INSERT OR UPDATE OF assigned_pro_id,cleaning_team_id,size_tier,status ON public.visits FOR EACH ROW EXECUTE FUNCTION public.cleaning_visit_staff_guard();